-- =============================================================================
-- HR documents: NDA and Experience Letter, generated by the server on the official templates and kept per employee.
--
--  * public.hr_documents      one row per generated PDF: the document type, the employee it belongs to (key + code + name taken from the
--                             HR record, never from the browser), the exact values that were printed, who generated it and when, and
--                             where the file is stored (private bucket "hr-documents"; the server writes it and signs short download links).
--  * private.hr_doc_employee  resolves an employee key to the HR record: the CRM account (key = profile id) or an HR-only record (key = 'HR:' + id).
--  * public.hr_document_prefill   what the record says + what is missing, for the form (HR staff only).
--  * public.hr_document_record    stores the reference of a file the server made, after checking again that this employee may get this letter.
--  * public.hr_documents_list / public.hr_document_get   a previously generated document, for HR staff (every download is audited).
--
-- Who: HR staff only (Super Admin, HR Admin Head, HR Assistant; not HR Recruiters) - private.is_hr_staff().
-- Additive and safe to run twice. Nothing existing is changed; nothing is deleted.
-- =============================================================================

create table if not exists public.hr_documents (
  id               uuid primary key default gen_random_uuid(),
  doc_type         text not null check (doc_type in ('NDA', 'EXPERIENCE')),
  employee_key     text not null,
  profile_id       uuid references public.profiles (id) on delete set null,
  hr_record_id     text,
  employee_code    text not null,
  employee_name    text not null,
  fields           jsonb not null,
  file_name        text not null,
  storage_provider text not null default 'SUPABASE' check (storage_provider in ('SUPABASE', 'R2')),
  storage_bucket   text not null,
  storage_path     text not null unique,
  storage_ref      text,
  storage_etag     text,
  size_bytes       integer not null check (size_bytes > 0),
  sha256           text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  generated_by     uuid references public.profiles (id) on delete set null,
  generated_by_name text,
  created_at       timestamptz not null default now()
);
create index if not exists hr_documents_employee_idx on public.hr_documents (employee_key, created_at desc);
create index if not exists hr_documents_type_idx on public.hr_documents (doc_type, created_at desc);
alter table public.hr_documents enable row level security;
-- no policy and no grant: the rows are reached only through the security definer functions below
revoke all on public.hr_documents from anon, authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('hr-documents', 'hr-documents', false, 5242880, array['application/pdf'])
on conflict (id) do nothing;

create or replace function private.hr_doc_require_staff()
returns void language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_hr_staff() then
    raise exception 'FORBIDDEN: Only HR staff can generate or open HR documents.' using errcode = '42501';
  end if;
end $$;
revoke all on function private.hr_doc_require_staff() from public, anon;
grant execute on function private.hr_doc_require_staff() to authenticated, service_role;

-- The HR record behind an employee key. No row = no such employee (or a Super Admin / rejected account, who are not payroll staff).
create or replace function private.hr_doc_employee(p_key text)
returns table (employee_key text, profile_id uuid, hr_record_id text, employee_code text, full_name text, email text, department_name text,
               designation text, joining_date date, left_date date, hr_status text, account_status text, separated boolean)
language plpgsql stable security definer set search_path = '' as $$
begin
  if p_key like 'HR:%' then
    return query
      select p_key, null::uuid, h.id, h.id, h.name, nullif(lower(btrim(coalesce(h.email, ''))), ''), coalesce(d.name, h.department_id),
             nullif(btrim(coalesce(h.designation, '')), ''), private.hr_safe_date(h.joining_date), private.hr_safe_date(h.data ->> 'leftDate'),
             h.status, null::text, (coalesce(h.status, '') = 'Left')
        from public.hr_employees h
        left join public.departments d on d.slug = h.department_id
       where h.id = substr(p_key, 4) and h.profile_id is null
         and not exists (select 1 from public.profiles q where q.email = lower(btrim(coalesce(h.email, ''))) and q.status <> 'REJECTED');
  elsif p_key ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return query
      select p.id::text, p.id, h.id, coalesce(h.id, 'EMP-' || upper(left(p.id::text, 8))), p.full_name, nullif(lower(btrim(coalesce(p.email, ''))), ''), d.name,
             coalesce(nullif(btrim(coalesce(p.position, '')), ''), nullif(btrim(coalesce(h.designation, '')), '')),
             coalesce(x.joining_date, private.hr_safe_date(h.joining_date)), private.hr_safe_date(h.data ->> 'leftDate'),
             h.status, p.status::text, (coalesce(h.status, '') = 'Left' or p.status in ('REVOKED', 'SUSPENDED'))
        from public.profiles p
        left join public.departments d on d.id = p.department_id
        left join public.employee_personal_details x on x.profile_id = p.id
        left join lateral (
          select y.* from public.hr_employees y
           where y.profile_id = p.id or (y.profile_id is null and lower(trim(coalesce(y.email, ''))) = p.email)
           order by (y.profile_id is not null) desc, y.created_at limit 1) h on true
       where p.id = p_key::uuid and p.role <> 'SUPER_ADMIN' and p.status <> 'REJECTED';
  end if;
end $$;
revoke all on function private.hr_doc_employee(text) from public, anon, authenticated;

-- What stops a letter. An empty list means the employment details are on record and consistent.
create or replace function private.hr_doc_problems(p_type text, p_key text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  e record;
  v jsonb := '[]'::jsonb;
begin
  select * into e from private.hr_doc_employee(p_key);
  if not found then
    return jsonb_build_array(jsonb_build_object('code', 'NOT_FOUND', 'message', 'This employee is not in the HR directory.'));
  end if;
  if nullif(btrim(e.full_name), '') is null then
    v := v || jsonb_build_array(jsonb_build_object('code', 'NO_NAME', 'message', 'The HR record has no name.'));
  end if;
  if p_type = 'EXPERIENCE' then
    if e.joining_date is null then
      v := v || jsonb_build_array(jsonb_build_object('code', 'NO_JOINING_DATE', 'message', 'The HR record has no joining date. Add it to the employee''s record first.'));
    elsif e.joining_date > private.hr_today() then
      v := v || jsonb_build_array(jsonb_build_object('code', 'JOINING_DATE_IN_THE_FUTURE', 'message', 'The joining date on record is in the future.'));
    end if;
    if not e.separated then
      v := v || jsonb_build_array(jsonb_build_object('code', 'NOT_SEPARATED', 'message', 'An Experience Letter is issued after the employee has left. Mark the employee as Left in HR & Operations first.'));
    end if;
    if e.left_date is not null and e.joining_date is not null and e.left_date < e.joining_date then
      v := v || jsonb_build_array(jsonb_build_object('code', 'LEFT_BEFORE_JOINING', 'message', 'The last working date on record is before the joining date. Correct the record first.'));
    end if;
  end if;
  return v;
end $$;
revoke all on function private.hr_doc_problems(text, text) from public, anon, authenticated;

create or replace function public.hr_document_prefill(p_employee_key text, p_doc_type text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  e record;
  v_problems jsonb;
begin
  perform private.hr_doc_require_staff();
  if p_doc_type not in ('NDA', 'EXPERIENCE') then
    raise exception 'VALIDATION_ERROR: Choose the NDA or the Experience Letter.' using errcode = 'P0001';
  end if;
  select * into e from private.hr_doc_employee(p_employee_key);
  if not found then
    raise exception 'NOT_FOUND: This employee is not in the HR directory.' using errcode = 'P0001';
  end if;
  v_problems := private.hr_doc_problems(p_doc_type, p_employee_key);
  return jsonb_build_object(
    'employee', jsonb_build_object(
      'key', e.employee_key, 'code', e.employee_code, 'name', e.full_name, 'email', e.email, 'department', e.department_name,
      'designation', e.designation, 'joiningDate', e.joining_date, 'lastWorkingDate', e.left_date,
      'status', case when e.separated then 'Left' else coalesce(e.hr_status, 'Full-Time') end, 'separated', e.separated),
    'problems', v_problems,
    'ready', jsonb_array_length(v_problems) = 0,
    'today', private.hr_today());
end $$;
revoke all on function public.hr_document_prefill(text, text) from public, anon;
grant execute on function public.hr_document_prefill(text, text) to authenticated;

-- Called by the server after it stored the PDF. The employee, code and joining date are the record's; the printed values are kept as they were.
create or replace function public.hr_document_record(
  p_employee_key text, p_doc_type text, p_fields jsonb, p_file_name text,
  p_provider text, p_bucket text, p_path text, p_ref text, p_etag text, p_size integer, p_sha256 text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  e record;
  v_problems jsonb;
  v_actor text;
  v_id uuid;
  v_row public.hr_documents;
begin
  perform private.hr_doc_require_staff();
  if p_doc_type not in ('NDA', 'EXPERIENCE') then
    raise exception 'VALIDATION_ERROR: Choose the NDA or the Experience Letter.' using errcode = 'P0001';
  end if;
  select * into e from private.hr_doc_employee(p_employee_key);
  if not found then
    raise exception 'NOT_FOUND: This employee is not in the HR directory.' using errcode = 'P0001';
  end if;
  v_problems := private.hr_doc_problems(p_doc_type, p_employee_key);
  if jsonb_array_length(v_problems) > 0 then
    raise exception 'VALIDATION_ERROR: %', v_problems -> 0 ->> 'message' using errcode = 'P0001';
  end if;
  if p_fields is null or jsonb_typeof(p_fields) <> 'object' or nullif(btrim(coalesce(p_fields ->> 'employeeName', '')), '') is null then
    raise exception 'VALIDATION_ERROR: The document values are missing.' using errcode = 'P0001';
  end if;
  if p_doc_type = 'EXPERIENCE' then
    if (p_fields ->> 'joiningDate')::date is distinct from e.joining_date then
      raise exception 'VALIDATION_ERROR: The joining date must be the one on the employee''s record.' using errcode = 'P0001';
    end if;
    if (p_fields ->> 'lastWorkingDate')::date < e.joining_date then
      raise exception 'VALIDATION_ERROR: The last working date is before the joining date.' using errcode = 'P0001';
    end if;
    if (p_fields ->> 'letterDate')::date < (p_fields ->> 'lastWorkingDate')::date then
      raise exception 'VALIDATION_ERROR: The letter date cannot be before the last working date.' using errcode = 'P0001';
    end if;
  end if;
  if p_path is null or p_bucket is distinct from 'hr-documents' or p_size is null or p_size <= 0 or p_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'VALIDATION_ERROR: The stored file reference is not valid.' using errcode = 'P0001';
  end if;
  select full_name into v_actor from public.profiles where id = auth.uid();
  insert into public.hr_documents (doc_type, employee_key, profile_id, hr_record_id, employee_code, employee_name, fields, file_name,
                                   storage_provider, storage_bucket, storage_path, storage_ref, storage_etag, size_bytes, sha256, generated_by, generated_by_name)
  values (p_doc_type, e.employee_key, e.profile_id, e.hr_record_id, e.employee_code, e.full_name, p_fields, p_file_name,
          case when p_provider = 'R2' then 'R2' else 'SUPABASE' end, p_bucket, p_path, p_ref, p_etag, p_size, p_sha256, auth.uid(), v_actor)
  returning * into v_row;
  perform private.write_audit('HR_DOCUMENT_GENERATED', 'hr_document', v_row.id, null, null,
    jsonb_build_object('type', p_doc_type, 'employeeKey', e.employee_key, 'employeeCode', e.employee_code, 'fileName', p_file_name));
  return jsonb_build_object('id', v_row.id, 'type', v_row.doc_type, 'employeeKey', v_row.employee_key, 'employeeCode', v_row.employee_code,
    'employeeName', v_row.employee_name, 'fileName', v_row.file_name, 'sizeBytes', v_row.size_bytes, 'fields', v_row.fields,
    'generatedBy', v_row.generated_by_name, 'createdAt', v_row.created_at);
end $$;
revoke all on function public.hr_document_record(text, text, jsonb, text, text, text, text, text, text, integer, text) from public, anon;
grant execute on function public.hr_document_record(text, text, jsonb, text, text, text, text, text, text, integer, text) to authenticated;

create or replace function public.hr_documents_list(p_employee_key text default null, p_doc_type text default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  perform private.hr_doc_require_staff();
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', d.id, 'type', d.doc_type, 'employeeKey', d.employee_key, 'employeeCode', d.employee_code,
             'employeeName', d.employee_name, 'fileName', d.file_name, 'sizeBytes', d.size_bytes, 'fields', d.fields,
             'generatedBy', d.generated_by_name, 'createdAt', d.created_at) order by d.created_at desc)
      from (select * from public.hr_documents x
             where (p_employee_key is null or x.employee_key = p_employee_key) and (p_doc_type is null or x.doc_type = p_doc_type)
             order by x.created_at desc limit 200) d), '[]'::jsonb);
end $$;
revoke all on function public.hr_documents_list(text, text) from public, anon;
grant execute on function public.hr_documents_list(text, text) to authenticated;

-- Where a stored document lives, for HR staff. Opening a document is written to the audit log.
create or replace function public.hr_document_get(p_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  d public.hr_documents;
begin
  perform private.hr_doc_require_staff();
  select * into d from public.hr_documents where id = p_id;
  if not found then
    raise exception 'NOT_FOUND: This document was not found.' using errcode = 'P0001';
  end if;
  perform private.write_audit('HR_DOCUMENT_OPENED', 'hr_document', d.id, null, null,
    jsonb_build_object('type', d.doc_type, 'employeeKey', d.employee_key, 'employeeCode', d.employee_code));
  return jsonb_build_object('id', d.id, 'fileName', d.file_name, 'storageProvider', d.storage_provider, 'storageBucket', d.storage_bucket, 'storagePath', d.storage_path);
end $$;
revoke all on function public.hr_document_get(uuid) from public, anon;
grant execute on function public.hr_document_get(uuid) to authenticated;

notify pgrst, 'reload schema';
